def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for degree in range(n, -1, -1):
        coeff = coeffs[n - degree]
        if coeff == 0:
            continue
        if degree == 0:
            term = str(abs(coeff))
        elif degree == 1:
            if coeff == -1:
                term = '-x'
            elif coeff == 1:
                term = 'x'
            else:
                term = f'{coeff}x'
        else:
            if coeff == -1:
                term = f'-x^{degree}'
            elif coeff == 1:
                term = f'x^{degree}'
            else:
                term = f'{coeff}x^{degree}'
        terms.append(term)
    return ''.join(terms)

