def decode(encoded: str, original: str, message: str) -> str:
    # Create a mapping from encoded letters to original letters
    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping and mapping[enc] != orig:
            return "Failed"
        mapping[enc] = orig

    # Map the message using the created mapping
    decoded_message = []
    for char in message:
        decoded_message.append(mapping.get(char, char))

    return "".join(decoded_message)

