def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    :param n: The original integer number to transform.
    :param rules: A list of transformation rules, where each rule is represented as a tuple (x, y).
    :return: The total count of unique numbers that can be generated.
    """
    queue = deque([n])
    visited = set()
    visited.add(n)

    while queue:
        current_number = queue.popleft()
        current_digits = list(str(current_number))

        for i, digit in enumerate(current_digits):
            for x, y in rules:
                if int(digit) == x:
                    new_digit = str(y)
                    new_number = int(''.join(current_digits[:i] + [new_digit] + current_digits[i+1:]))
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

