def catalan_number(n: int) -> int:
    if n <= 1:
        return 1

    # Initialize a list to store Catalan numbers
    catalan = [0 for _ in range(n + 1)]

    # Base case
    catalan[0] = catalan[1] = 1

    # Fill the list using the recursive relation
    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - 1 - j]

    return catalan[n]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the maximum value for each time limit
    dp = [0] * (T + 1)

    # Iterate over each herb
    for time, value in herbs:
        # Update the dp array from the back to avoid using the same herb multiple times
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    # The maximum value that can be picked within the time limit T
    return dp[T]

