def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Calculate the maximum height that can be achieved by a choir formation
    max_choir_height = 0
    for i in range(n):
        increasing = 1
        decreasing = 1
        for j in range(i):
            if heights[i] > heights[j]:
                increasing = max(increasing, increasing + 1)
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                decreasing = max(decreasing, decreasing + 1)
        max_choir_height = max(max_choir_height, increasing + decreasing - 1)

    # The minimum number of students to leave is the total number
    # of students minus the maximum choir height
    return n - max_choir_height

